PRAGMA foreign_keys=ON;
-- MIGRATION 1: base
CREATE TABLE roles (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, role_id INTEGER NOT NULL REFERENCES roles(id) ON DELETE RESTRICT, email TEXT NOT NULL UNIQUE);
CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, total NUMERIC NOT NULL DEFAULT 0, CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX idx_users_role ON users(role_id);
CREATE VIEW active_users AS SELECT id,email FROM users;
CREATE TRIGGER trg_users_touch AFTER UPDATE ON users BEGIN SELECT 1; END;
